import{_ as t,o as i,c as n,ah as r}from"./chunks/framework.DDXs_i7t.js";const d=JSON.parse(`{"title":"March 17: Wöginger Strikes Back – Schmid's Testimony Labeled 'Fiction'","description":"8th trial day in Linz: Wöginger denies exercising pressure, and witnesses describe feeling 'unwanted' during the post-filling process.","frontmatter":{"title":"March 17: Wöginger Strikes Back – Schmid's Testimony Labeled 'Fiction'","description":"8th trial day in Linz: Wöginger denies exercising pressure, and witnesses describe feeling 'unwanted' during the post-filling process.","date":"2026-03-17T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/2026-03-17-woeginger-gegenangriff.md","filePath":"en/logbuch/2026-03-17-woeginger-gegenangriff.md"}`),o={name:"en/logbuch/2026-03-17-woeginger-gegenangriff.md"};function a(s,e,g,c,h,u){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="⚖️-march-17-woginger-strikes-back-–-schmid-s-testimony-labeled-fiction" tabindex="-1">⚖️ March 17: Wöginger Strikes Back – Schmid&#39;s Testimony Labeled &#39;Fiction&#39; <a class="header-anchor" href="#⚖️-march-17-woginger-strikes-back-–-schmid-s-testimony-labeled-fiction" aria-label="Permalink to &quot;⚖️ March 17: Wöginger Strikes Back – Schmid&#39;s Testimony Labeled &#39;Fiction&#39;&quot;">​</a></h1><p>It is <strong>Tuesday, March 17, 2026 (18:02 PM)</strong>. The eighth day of trial at the Linz Regional Court marks a turning point in August Wöginger&#39;s defense strategy.</p><h3 id="the-citizen-surgery-euphemism" tabindex="-1"><strong>The &quot;Citizen Surgery&quot; Euphemism</strong> <a class="header-anchor" href="#the-citizen-surgery-euphemism" aria-label="Permalink to &quot;**The &quot;Citizen Surgery&quot; Euphemism**&quot;">​</a></h3><p>Today, Wöginger gave an extensive statement in which he attacked the testimony of crown witness Thomas Schmid head-on. According to Wöginger, he &quot;never gave Schmid an order.&quot; The interventions were merely the forwarding of requests from &quot;citizen surgeries&quot; (Bürgersprechtage).</p><ul><li><strong>Wöginger&#39;s Narrative:</strong> He is merely a &quot;representative of the people&quot; who stands up for his citizens.</li><li><strong>The Prosecution (WKStA):</strong> Sees it as a targeted incitement to abuse of office to hoist an ÖVP mayor into the position of tax office head.</li></ul><h3 id="the-feeling-of-being-unwanted" tabindex="-1"><strong>The Feeling of Being &quot;Unwanted&quot;</strong> <a class="header-anchor" href="#the-feeling-of-being-unwanted" aria-label="Permalink to &quot;**The Feeling of Being &quot;Unwanted&quot;**&quot;">​</a></h3><p>Particularly distressing today were the testimonies of competing candidates. One witness described having a clear feeling during the 2017 application process of being <strong>&quot;unwanted.&quot;</strong> A classic element in our &quot;system of patronage.&quot;</p><h3 id="significance-for-the-horten-mystery" tabindex="-1"><strong>Significance for the &quot;Horten Mystery&quot;</strong> <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;**Significance for the &quot;Horten Mystery&quot;**&quot;">​</a></h3><p>For our mockumentary, today is a gold mine for <strong>Part 4: The Political Love Story</strong>:</p><ol><li><strong>Language Analysis:</strong> We will include the term &quot;citizen surgery&quot; in our &quot;Pointillism Oracle.&quot; It is the perfect synonym for &quot;intervention.&quot;</li><li><strong>Character Development:</strong> The sharp demarcation from Schmid shows the cracks in the old power structure.</li><li><strong>The Aesthetics of Rejection:</strong> The testimony about the feeling of being &quot;unwanted&quot; in one&#39;s own state will be a central emotional note in Part 4.</li></ol><hr><p><strong>&quot;When power disguises itself as citizen service, corruption begins to become invisible.&quot;</strong></p><p>👉 <a href="/en/statistik.html">Analyze the current statistics</a> 👉 <a href="/en/recherche/gericht-woeginger-braunau.html">Background: The Braunau Tax Office case</a></p><hr><p><em>Reporting from March 17, 2026. The countdown to the verdict (April 21) is on.</em></p>',15)])])}const f=t(o,[["render",a]]);export{d as __pageData,f as default};
